begin
  select u.id into v_uid from auth.users u where lower(btrim(u.email)) = v_email limit 1;

  if v_uid is not null then
    delete from public.products where user_id = v_uid;

    insert into public.products (user_id, data)
    select v_uid, elem
    from jsonb_array_elements(v_catalog) as t(elem);
  else
    raise notice 'seed_ajay_products_catalog: no auth.users row for %; skipping products seed.', v_email;
  end if;
end
$seed$;
